  <div class="content">
    <!-- Tab Váltás -->
    <div class="tabs">
      <button id="btn-home" onclick="showTab('home')" class="active">Kezdőlap</button>
      <button id="btn-protein" onclick="showTab('protein')">Protein Elemzés</button>
