<div id="page-protein" class="hidden">
  <h2>Protein Elemzés (AlphaFold3)</h2>
  <label>Szekvencia (10-5120 aminosav):</label>
  <textarea id="protein-seq" placeholder="Pl.: MGLSDGEWQLVL..."></textarea>
  <label>Variánsok (pl. A15V, L22P vagy több, vesszővel):</label>
  <input id="mutations" type="text" placeholder="pl. G12D, V600E" />
