  <div id="protein-loading" class="spinner hidden"></div>
  <div id="protein-result" class="hidden">
    <h3>Eredmények:</h3>
    <b>Struktúra letöltése:</b> <button onclick="downloadPDB()">PDB letöltése</button>
    <div id="ngl-viewport" style="width:100%;height:420px;margin:1em 0;background:#eef;"></div>
    <canvas id="protein-chart" height="110"></canvas>
    <div id="protein-text"></div>
  </div>
</div>

<!-- --- Genom --- -->
<div id="page-genome" class="hidden">
  <h2>Genom Elemzés (AlphaGenome)</h2>
  <label>Szekvencia (DNS vagy RNS, min 100b):</label>
  <textarea id="genome-seq" placeholder="ATGGCCT..."></textarea>
  <label>Organizmus:</label>
  <select id="genome-org">
    <option value="human">Ember</option>
    <option value="mouse">Egér</option>
  </select>
  <button onclick="submitGenome()">Elemzés indítása</button>
  <div id="genome-error" class="error"></div>
  <div id="genome-loading" class="spinner hidden"></div>
  <div id="genome-result" class="hidden">
    <h3>Génexpressziós előrejelzés/grafikon</h3>
    <canvas id="genome-chart" height="110"></canvas>
    <div id="genome-text"></div>
  </div>
</div>

<!-- --- Kép AI --- -->
<div id="page-image" class="hidden">
  <h2>AI Kép Generálás (OpenAI DALL·E)</h2>
  <input id="img-prompt" type="text" placeholder="Írj le egy képet magyarul vagy angolul..." />
  <button onclick="submitImage()">Kép generálása</button>
  <div id="image-error" class="error"></div>
  <div id="image-loading" class="spinner hidden"></div>
  <div id="image-result" class="hidden">
    <img id="gen-img" src="" style="max-width: 400px;" />
  </div>
</div>

<!-- --- TTS --- -->
<div id="page-tts" class="hidden">
  <h2>Szöveg → Hang (OpenAI TTS)</h2>
  <input id="tts-text" type="text" placeholder="Add meg a felolvasandó szöveget..." />
  <button onclick="submitTTS()">Generálás és lejátszás</button>
  <div id="tts-error" class="error"></div>
  <div id="tts-loading" class="spinner hidden"></div>
  <div id="tts-result" class="hidden">
    <audio id="tts-audio" controls></audio>
  </div>
</div>

<!-- --- Kód AI --- -->
<div id="page-code" class="hidden">
  <h2>Kódgenerálás (OpenAI, GCP...)</h2>
  <label>Kód leírás:</label>
  <textarea id="code-desc" placeholder="Pl.: írj egy Python függvényt amely..."></textarea>
  <button onclick="submitCode()">Generálás</button>
  <div id="code-error" class="error"></div>
  <div id="code-loading" class="spinner hidden"></div>
  <div id="code-result" class="hidden">
    <pre id="code-output"></pre>
  </div>
</div>

<!-- --- Névjegy --- -->
<div id="page-about" class="hidden">
  <h2>Névjegy</h2>
  <p>JADED AI – Teljes körű magyar bioinformatikai és AI platform. <br/>2024 Kiskunhalas | <span class="small">Backend: FastAPI • Frontend: Vanilla JS</span></p>
</div>
  </div>

<script>
let currentTab = 'home';
function showTab(tab) {
  // Tab gombokat kiemeli
  ['home','protein','genome','image','tts','about','code'].forEach(t=>{
    document.getElementById('page-'+t).classList.add('hidden');
    let btn = document.getElementById('btn-'+t);
    if(btn) btn.classList.remove('active');
  });
  document.getElementById('page-'+tab).classList.remove('hidden');
  let activeBtn = document.getElementById('btn-'+tab);
  if(activeBtn) activeBtn.classList.add('active');
  currentTab = tab;
}

/// --- Aszinkron API hívások, validáció, stb ---

// PDB letöltés
let lastPDB = "";
function downloadPDB() {
  if (!lastPDB) return;
  let blob = new Blob([lastPDB], {type: "text/plain"});
  let a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "structure.pdb";
  a.click();
}

function validAmino(seq) {
  return /^[ACDEFGHIKLMNPQRSTVWYXBZJOU*\-\s]{10,5120}$/i.test(seq.replace(/\s/g,""));
}
function validDNA(seq) {
  return /^[ATCGRYSWKMBDHVN\-\s]{100,}$/i.test(seq.replace(/\s/g,""));
}
function showError(where, msg) {
  document.getElementById(where).textContent = msg;
}
function showLoading(where, show) {
  document.getElementById(where).classList.toggle("hidden", !show);
}
function hideResult(t) {
  document.getElementById(t+"-result").classList.add('hidden');
}
function showResult(t) {
  document.getElementById(t+"-result").classList.remove('hidden');
}

// --- Protein ---

function submitProtein() {
  let seq = document.getElementById('protein-seq').value.trim();
  let muts = document.getElementById('mutations').value.trim();
  showError('protein-error', ""); hideResult('protein');
  if (!validAmino(seq)) { showError('protein-error', "Hibás vagy túl rövid aminosav szekvencia!"); return; }
  showLoading('protein-loading', true);
  fetch("/api/alphafold3/protein_analysis",{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sequence:seq,mutations:muts})})
    .then(r=>r.json()).then(data=>{
      showLoading('protein-loading', false);
      if (data.status==="error"||data.error) {showError('protein-error', data.error||"Backend hiba!"); return;}
      // PDB
      lastPDB = data.analysis_result?.structure_pdb || "";
      // 3D nézet
      let stage = new NGL.Stage("ngl-viewport");
      stage.removeAllComponents();
      if(lastPDB) {
        stage.loadFile(new Blob([lastPDB],{type:'text/plain'}), {ext:"pdb"}).then(c=>{
          c.addRepresentation("cartoon");
          c.autoView();
        });
      }
      // pLDDT grafikon (ha van)
      let chartData = data.analysis_result?.predicted_lddt || [];
      let labels = data.analysis_result?.residue_numbers || chartData.map((_,i)=>i+1);
      let ctx = document.getElementById('protein-chart').getContext('2d');
      new Chart(ctx, {
        type:'line',
        data: {labels, datasets:[{label: 'pLDDT', data: chartData, borderColor: "#007bff", fill:true}]},
        options: {responsive:true,scales:{y:{min:0, max:100}}}
      });
      // Szöveges annotáció
      document.getElementById('protein-text').innerHTML = 
        "<b>Konfidencia:</b> "+(data.analysis_result.confidence_score||"–")+"<br/>"+
        (data.analysis_result.secondary_structure?"Másodlagos struktúra: "+data.analysis_result.secondary_structure:"");
      showResult('protein');
    })
    .catch(e=>{showLoading('protein-loading', false);showError('protein-error', 'Hálózati/API hiba: '+e);});
}

// --- Genome ---

function submitGenome() {
  let seq = document.getElementById('genome-seq').value.trim();
  let org = document.getElementById('genome-org').value;
  hideResult('genome'); showError('genome-error', "");
  if(!validDNA(seq)) {showError('genome-error', "Hibás vagy túl rövid DNS szekvencia!"); return;}
  showLoading('genome-loading', true);
  fetch("/api/alphagenome/gene_expression",{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sequence:seq,organism:org})})
    .then(r=>r.json()).then(data=>{
      showLoading('genome-loading', false);
      if(data.status==="error"||data.error){showError('genome-error', data.error||"Backend hiba!"); return;}
      let chart = data.expression_values||data.result;
      let ctx = document.getElementById('genome-chart').getContext('2d');
      new Chart(ctx, {type:'bar',
        data: {labels: chart.map((_,i)=>i+1), datasets:[{label:'Expresszió', data: chart}]},
        options:{responsive:true}});
      document.getElementById('genome-text').textContent = data.message||"Elemzés kész.";
      showResult('genome');
    }).catch(e=>{showLoading('genome-loading', false);showError('genome-error','Hálózati/API hiba: '+e);});
}

// --- Kép generálás ---

function submitImage(){
  let prompt = document.getElementById('img-prompt').value.trim();
  if (!prompt) {showError('image-error', "Adj meg leírást!"); return;}
  hideResult('image'); showError('image-error',"");
  showLoading('image-loading',true);
  fetch("/api/openai/generate_image",{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt})})
    .then(r=>r.json()).then(data=>{
      showLoading('image-loading',false);
      if (!data.images||data.error){ showError('image-error', (data.error||"Hiba!")); return;}
      document.getElementById('gen-img').src = data.images[0].url;
      showResult('image');
    }).catch(e=>{showLoading('image-loading',false);showError('image-error','Hálózati/API hiba: '+e);});
}

// --- TTS ---

function submitTTS(){
  let text = document.getElementById('tts-text').value.trim();
  if(!text){showError('tts-error',"Írj be szöveget!");return;}
  hideResult('tts'); showError('tts-error',""); showLoading('tts-loading',true);
  fetch("/api/openai/text_to_speech",{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})})
    .then(r=>r.json()).then(data=>{
      showLoading('tts-loading',false);
      if(!data.audio_url&& !data.audio_base64){showError('tts-error', data.error||"Backend hiba"); return;}
      let audio = document.getElementById('tts-audio');
      if(data.audio_url) {audio.src = data.audio_url;}
      else if(data.audio_base64) {audio.src="data:audio/mp3;base64,"+data.audio_base64;}
      showResult('tts');
    }).catch(e=>{showLoading('tts-loading',false);showError('tts-error','Hálózati/API hiba: '+e);});
}

// --- Kód AI ---

function submitCode(){
  let desc = document.getElementById('code-desc').value.trim();
  hideResult('code'); showError('code-error',"");
  if(!desc){showError('code-error',"Add meg a kód leírását!"); return;}
  showLoading('code-loading',true);
  fetch("/api/code/generate",{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:desc})})
    .then(r=>r.json()).then(data=>{
      showLoading('code-loading',false);
      if(!data.code && !data.result){ showError('code-error', data.error||"Backend válasz hiba"); return;}
      document.getElementById('code-output').textContent = data.code || data.result;
      showResult('code');
    }).catch(e=>{showLoading('code-loading',false); showError('code-error','Hálózati/API hiba: '+e);});
}

// --- TAB alapértelmezett: home
showTab('home');

// --- Valós idejű validáció ---
document.getElementById('protein-seq').addEventListener('input',function(){
  let v = validAmino(this.value.trim()); 
  this.style.borderColor = v?"#41b667":"#da2727";
});
document.getElementById('genome-seq').addEventListener('input',function(){
  let v = validDNA(this.value.trim());
  this.style.borderColor = v?"#41b667":"#da2727";
});
</script>
</body>
</html>
```

## Mire jó ez, mit tartalmaz?

- **Frontend egy fájlban**: Teljes platform – több oldal, modul, spinner, hibakezelés, letöltés, vizualizációk, magyar nyelv, valós idejű validáció, aszinkron API-kezelés.
- **Nem helyettesíti** a modern React, Vue, Angular alapú, teljes alkalmazás-architektúrát.
- **Használható** demo/prototípus vagy single-file deployment esetén, ahol minden frontend logikát index.html-ben akarsz tartani.
- **Ne feledd**: egyes API végpontokat, 3D nézegető funkciókat vagy grafikonokat lehet demo módon implementálni HTML/JS-ben, viszont nagyobb projektnél érdemes átállni komponens alapú keretrendszerre.

**Ha szeretnéd tovább bővíteni (pl. fájlfeltöltéssel, munkamenet mentéssel, helyi eredmény-archívummal stb.), ezt külön jelezd!**
